<?php
require_once dirname(__DIR__,3).'/app/bootstrap.php';api_rate_limit('v1-listings',100,60);
$q=trim((string)($_GET['q']??''));$city=trim((string)($_GET['city']??''));$category=trim((string)($_GET['category']??''));$page=max(1,min(1000,(int)($_GET['page']??1)));$limit=max(1,min(40,(int)($_GET['limit']??20)));
$where=["status='published'"];$params=[];if($q!==''){$where[]='(name LIKE :q OR description LIKE :q OR tags LIKE :q OR location LIKE :q OR city LIKE :q)';$params[':q']='%'.text_substr($q,0,100).'%';}if($city!==''){$where[]='city LIKE :city';$params[':city']='%'.text_substr($city,0,100).'%';}if($category!==''&&in_array($category,categories(),true)){$where[]='category=:cat';$params[':cat']=$category;}$w=implode(' AND ',$where);$count=db()->prepare('SELECT COUNT(*) FROM listings WHERE '.$w);$count->execute($params);$total=(int)$count->fetchColumn();$s=db()->prepare('SELECT * FROM listings WHERE '.$w.' ORDER BY sponsored DESC,featured DESC,name LIMIT :limit OFFSET :offset');foreach($params as $k=>$v)$s->bindValue($k,$v);$s->bindValue(':limit',$limit,PDO::PARAM_INT);$s->bindValue(':offset',($page-1)*$limit,PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll();json_response(['data'=>array_map(fn($l)=>listing_public_payload($l,false),$rows),'meta'=>['page'=>$page,'limit'=>$limit,'total'=>$total,'pages'=>(int)ceil($total/$limit)]]);
